) RETURNS SETOF "__mj_bizappssales"."vwSalesContacts" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappssales"."SalesContact"
        (
