CREATE OR REPLACE FUNCTION "__mj_bizappssales"."spCreateDealType"(
    p_id UUID DEFAULT NULL,
    p_code varchar(40) DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_requirescontract BOOLEAN DEFAULT NULL,
    p_requiresrenewalsource BOOLEAN DEFAULT NULL,
    p_defaultpipelineid_clear boolean DEFAULT false,
    p_defaultpipelineid UUID DEFAULT NULL,
    p_displayrank int DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj_bizappssales"."vwDealTypes" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappssales"."DealType"
        (
            "ID",
            "Code",
                "Name",
                "Description",
                "RequiresContract",
                "RequiresRenewalSource",
                "DefaultPipelineID",
                "DisplayRank",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_code,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                COALESCE(p_requirescontract, FALSE),
                COALESCE(p_requiresrenewalsource, FALSE),
                CASE WHEN p_defaultpipelineid_clear = true THEN NULL ELSE COALESCE(p_defaultpipelineid, NULL) END,
                COALESCE(p_displayrank, 0),
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappssales"."vwDealTypes"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
