) RETURNS SETOF "__mj_bizappssales"."vwForecastSnapshots" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj_bizappssales"."ForecastSnapshot"
        (
            "ID",
            "CompanyID",
                "PipelineID",
                "OwnerEmployeeID",
                "PeriodStart",
                "PeriodEnd",
                "CapturedAt",
                "CommitAmount",
                "BestCaseAmount",
                "PipelineAmount",
                "ClosedAmount",
                "SnapshotJSON"
        )
    VALUES
        (
            v_new_id,
            p_companyid,
                CASE WHEN p_pipelineid_clear = true THEN NULL ELSE COALESCE(p_pipelineid, NULL) END,
                CASE WHEN p_owneremployeeid_clear = true THEN NULL ELSE COALESCE(p_owneremployeeid, NULL) END,
