                CASE WHEN p_closedamount_clear = true THEN NULL ELSE COALESCE(p_closedamount, NULL) END,
                CASE WHEN p_snapshotjson_clear = true THEN NULL ELSE COALESCE(p_snapshotjson, NULL) END
