    p_description TEXT DEFAULT NULL,
    p_category_clear boolean DEFAULT false,
    p_category varchar(100) DEFAULT NULL,
    p_requiresnotes BOOLEAN DEFAULT NULL,
    p_iscompetitive BOOLEAN DEFAULT NULL,
    p_displayrank int DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF "__mj_bizappssales"."vwLossReasons" AS $$
DECLARE
