            "Code",
                "Name",
                "Description",
                "Category",
                "RequiresNotes",
                "IsCompetitive",
                "DisplayRank",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_code,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_category_clear = true THEN NULL ELSE COALESCE(p_category, NULL) END,
                COALESCE(p_requiresnotes, FALSE),
                COALESCE(p_iscompetitive, FALSE),
                COALESCE(p_displayrank, 0),
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj_bizappssales"."vwLossReasons"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
